cd /workspace && python3 - <<'EOF'
M=(1<<64)-1
def fnv(bs):
    h=14695981039346656037
    for b in bs:
        h=((h^b)*1099511628211)&M
    return h
def le32(v): return struct.pack('<I',v&0xffffffff)
import struct
target='f7c2a0394bc78590'
cands={
 'A [10,0xfffffffc]':[10,0xfffffffc],
 'B [0,0xfffffffc]':[0,0xfffffffc],
 'C [10,0xfffffffc] BE':[10,0xfffffffc],
}
for name,words in cands.items():
    if name.endswith('BE'):
        payload=b''.join(struct.pack('>I',w) for w in words)
    else:
        payload=b''.join(le32(w) for w in words)
    data=struct.pack('<Q',0)+bytes([0x0f,0x01])+payload
    print(name, '%016x'%fnv(data), fnv(data)==int(target,16))
# also try without complete flag etc
for mask in (0x0f,):
  for comp in (0,1):
    for words in ([10,0xfffffffc],[0,0xfffffffc]):
        data=struct.pack('<Q',0)+bytes([mask,comp])+b''.join(le32(w) for w in words)
        print(mask,comp,words,'%016x'%fnv(data))
EOF
